WITH review_input (
  professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
  attendance_required, grade_received, engagement_level, tags, created_at, import_key, course_ids
) AS (
  VALUES 
    (280::BIGINT, 'Es una persona que ve el paquete completo de usted, pero no le va a dar más de 1% para pasar si lo ocupa, sus exámenes son difíciles. Pero si usted pasa este curso con él siento que sus bases quedan muy robustas para siempre.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('45','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Exámenes retadores']::TEXT[], '2026-07-01T00:00:00+00:00'::TIMESTAMPTZ, 'f6517dc2785809e60b46934d5e6d3c4cb4cae90c453c4a2e88177c7e8be22081'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (280::BIGINT, 'El profe para mi es el profe ideal, es super buena nota, es muy agradable la clase, si lo lleva virtual es un queque, bastante facil pasar, y en realidad no es un curso dificil.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2026-02-18T00:00:00+00:00'::TIMESTAMPTZ, 'de510f68c9fb3e6515305f1dae316753af0494ad8be2f66603e9b1f05a0c82a8'::TEXT, ARRAY[1249]::BIGINT[]),
    (280::BIGINT, 'Yo no lo recomendaría si sabe poco o nada de Python, se vuelve difícil porque los casos de los quizes son distintos a lo ya visto en clase y califica duro. Con los laboratorios se puede salvar pero si lo quiere llevar más al suave no es la mejor opción'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchos exámenes', 'Exámenes retadores']::TEXT[], '2026-01-19T00:00:00+00:00'::TIMESTAMPTZ, 'ccdfbeca6df6a2290cfdd65fb9a197a8756b89b35b12f95f83c596ff86511869'::TEXT, ARRAY[1249]::BIGINT[]),
    (280::BIGINT, 'El profe explica bastante bien y evacua dudas, va bastante rápido con la materia. Estudie antes de las clases por los quices, los exámenes son bastante complicados, se puede recuperar con los laboratorios y la exposición. Es buena nota.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'La participación importa', 'Exámenes retadores']::TEXT[], '2025-06-17T00:00:00+00:00'::TIMESTAMPTZ, '984b1dd54eb87cd55cc8e53775ca25d0620bcaf609f49dd170121bb7bbc0b24a'::TEXT, ARRAY[1249]::BIGINT[]),
    (280::BIGINT, 'El profe es muy bueno, solamente que los exámenes son muy largos y el tiempo no es suficiente. Explica todo muy bien, y repite si es necesario. Es de lo mejor que me he encontrado, honestamente lo recomiendo full, solo ese detalle de los exámenes. Ah y califica relativamente duro.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria', 'Exámenes retadores']::TEXT[], '2025-02-05T00:00:00+00:00'::TIMESTAMPTZ, '1f85199d6910204360d9ead6016cfe96bb81d4109f513d4f7f4a3ce6d98d80b5'::TEXT, ARRAY[1151]::BIGINT[]),
    (280::BIGINT, 'Es un buen profesor, explica muy bien cada tema y con paciencia, evacua dudas. Lo que puede llegar a jugar una mala pasada es la evaluación ya que es 90% examenes, quiz cada semana. Excelente profe'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Respetado por los estudiantes', 'Inspirador']::TEXT[], '2024-12-03T00:00:00+00:00'::TIMESTAMPTZ, '2198acd8129ed73661bb179359cf38a0b025d75e0fef92b2652352a0cbdea08f'::TEXT, ARRAY[1020]::BIGINT[]),
    (280::BIGINT, 'El profe explica bien cada algoritmo. Se hacen quices cada semana. Los exámenes son virtuales. El proyecto es programar los algoritmos vistos en clase. Buen profe.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Pocos exámenes', 'Tomaría su clase nuevamente']::TEXT[], '2024-10-24T00:00:00+00:00'::TIMESTAMPTZ, 'd4c304dc707fdea0600b9b508f7fab5387e24226373bd5ef13044362d7ead823'::TEXT, ARRAY[1151]::BIGINT[]),
    (280::BIGINT, 'Es buen profe, el curso es bastante facil con solo poner atencion en las clases se logra pasar. Los examenes fueron virtuales y tenian bastantes preguntas pero eran de marcar con x. El profe hace quices todas las semanas pero califica suave. A veces se confunde un toque a la hora de aclarar dudas.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Brinda apoyo']::TEXT[], '2024-06-21T00:00:00+00:00'::TIMESTAMPTZ, '2fff7631b89d75801eeb799e9ac679f0c93ee4aa182c289bb5d4f3100826cb1c'::TEXT, ARRAY[1151]::BIGINT[]),
    (280::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Respetado por los estudiantes', 'Inspirador']::TEXT[], '2024-06-19T00:00:00+00:00'::TIMESTAMPTZ, '901dfc2763eb3fcd2d62a19efd8338073700b43a132ac15ae6b5007d927ecc97'::TEXT, ARRAY[1020]::BIGINT[]),
    (280::BIGINT, 'Los examenes son duros pero de marcar con X, además con dos 50 pasa fácil. El resto del curso es sencillo, con poner atención pasé el curso. Por ejemplo los quices los hacía solo con poner atención en clases. El proyecto es super realizable y el curso termina en semana 16.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Clase fácil', 'Da crédito extra', 'Exámenes retadores']::TEXT[], '2024-06-16T00:00:00+00:00'::TIMESTAMPTZ, '079a1897498479a9d48df0f1ec4852813502a735e55c641ff3f074331b35573e'::TEXT, ARRAY[1151]::BIGINT[]),
    (280::BIGINT, 'El profe es muy bueno para este curso, se ve materia los jueves y el martes se hace quiz y se introduce el tema del siguiente jueves. Los proyectos son un poco largos pero no muy complicados y los exámenes son de los mismos algoritmos que se ven en clase. Es bastante bueno para este curso y ayuda.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2024-06-12T00:00:00+00:00'::TIMESTAMPTZ, '8b6301157d6dfe2108a6a06b28c02a48b5f8019a95dc4db88337493857306b6e'::TEXT, ARRAY[1151]::BIGINT[]),
    (280::BIGINT, 'No lleven clases con este profesor. le gusta hacer sentir mal a los estudiantes para sentirse bien con él mismo. Además que los exámenes no son parecidos a lo que se ve en clase y tiene preferencia con aclarar las dudas con ciertos estudiantes y a los demás los deja a la deriva.'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2024-05-24T00:00:00+00:00'::TIMESTAMPTZ, 'a1f87ca42e9c5b8beb3e1f7ff50e9a362f5f37733d3e1516ee79df09bfbc585f'::TEXT, ARRAY[1020]::BIGINT[]),
    (280::BIGINT, 'Muy buen profesor para este curso. Hace quiz casi que semanalmente, pero ayuda para estudiar para los exámenes, los cuales tienen una dificultad moderadamente alta. Los proyectos que deja no son muy difíciles, pero hay que hacerlos con tiempo. Es bastante claro explicando. Muy recomendado'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Brinda apoyo', 'Exámenes retadores']::TEXT[], '2023-12-02T00:00:00+00:00'::TIMESTAMPTZ, '8804b54acbe9f4761f5d16e648577ac1e14c9e778043b8f1780402fda487de87'::TEXT, ARRAY[1151]::BIGINT[]),
    (280::BIGINT, 'Excelente profesor, hay que ser muy dedicado a la materia para ir al mismo ritmo que él la da, por lo tanto, hay que ser autodidacta (eso aprendí de él).'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'La participación importa', 'Asistencia obligatoria']::TEXT[], '2023-08-08T00:00:00+00:00'::TIMESTAMPTZ, '86bf34f71543945f403698f393d63e930f01d299b6809e3ca1cd59141ecb8f3e'::TEXT, ARRAY[1249]::BIGINT[]),
    (280::BIGINT, 'Es una porquería de profesor, no da materia, medio aclara dudas, le gusta jugar de vivo y en las defensas de proyectos o cosas así le gusta intimidar alumnos con plagio.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('45','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Asistencia obligatoria']::TEXT[], '2023-01-26T00:00:00+00:00'::TIMESTAMPTZ, '3effe63f3ba375895bd151e8a63c90dff39bd29d7fbbfc9d3777996e58e23a6c'::TEXT, ARRAY[1249]::BIGINT[]),
    (280::BIGINT, 'El mae deja 3 proyectos en web sencillos, los examenes son duros, los quices son fáciles junto con las tareas, al mae le gusta que la gente participe en clase, el mae es buena persona, lo recomiendo para personas que si se van a conectar a clases'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-12-05T00:00:00+00:00'::TIMESTAMPTZ, '1e80c961df513eb7c4db0d6f79a4409b38a1863d7fade0062ee4f8f3dc929f1f'::TEXT, ARRAY[1151]::BIGINT[]),
    (280::BIGINT, 'Las clases con este mae son un bostezo . Si va llevar con este playo mejor aprenda a ser autodidacta , porque no sabe nada . Es un dolor de bolas para aclarar dudas. No sé que está haciendo este profe en la escuela de computación .'::TEXT, 6.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-02-11T00:00:00+00:00'::TIMESTAMPTZ, '871fc8dd4d33f7653d7aa831b5dd497d17b8b8a0ed79f3cb01f49d9fbd50d84e'::TEXT, ARRAY[1020]::BIGINT[]),
    (280::BIGINT, 'Es buena gente, y en clases esta dispuesto a aclarar dudas de buena manera. Pero simplemente lo sentí muy desorganizado fuera de horas clase. ( hasta 1 día en responder una duda), algunos temas de los proyectos nos mando a buscarlos por internet. Me lleve una mala experiencia.'::TEXT, 2.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Clases largas']::TEXT[], '2021-02-10T00:00:00+00:00'::TIMESTAMPTZ, '0334c6cbcbfb6ef20c3425088fe780bbc277f9297083a511580a2bbf4bef6cab'::TEXT, ARRAY[1020]::BIGINT[]),
    (280::BIGINT, 'El peor profesor que me ha dado , no sabe explicar . Hay mejores profesores que este payaso . El curso con este mae es una mierda .'::TEXT, 6.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-02-07T00:00:00+00:00'::TIMESTAMPTZ, 'eb6dd779f58385fa3ec8b1fcfadc24edfeb388bef9864273bc6e6c58d0b5bbc9'::TEXT, ARRAY[1020]::BIGINT[]),
    (280::BIGINT, 'Se le debe dedicar tiempo suficiente a la práctica para tener buenas notas en quices y laboratorios que al final son de suma importancia.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores']::TEXT[], '2018-06-25T00:00:00+00:00'::TIMESTAMPTZ, 'a27e356d7b81ea0b5cd0f1535e44e55dc1a366c30dc0ed91d4a8cb306077030b'::TEXT, ARRAY[1249]::BIGINT[]),
    (280::BIGINT, 'El profe es pura vida, pero los examenes de intro son duros (excepto el ultimo examen, que es facil), hay que dedicar ciertas horas de estudio a estas materias, debido a que el hace quiz sorpresa y son muy importantes en la nota.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores', 'Deja trabajos largos']::TEXT[], '2018-06-25T00:00:00+00:00'::TIMESTAMPTZ, 'e6c975be3a7152a7cac8d0ec6eb699434bfeb5b54668635292551b119dfd7285'::TEXT, ARRAY[1020]::BIGINT[]),
    (280::BIGINT, 'Es un excelente profesor 100% recomendado se aprende mucho.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Respetado por los estudiantes']::TEXT[], '2018-05-15T00:00:00+00:00'::TIMESTAMPTZ, '66de7e61d744097c3219f5a118421ac7ccc0dc2a9466d0a0c96a7c1f53cf5ed5'::TEXT, ARRAY[1020]::BIGINT[]),
    (280::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Brinda apoyo', 'Deja trabajos largos']::TEXT[], '2017-06-26T00:00:00+00:00'::TIMESTAMPTZ, '22850e749c056d57f2e04e682dd2de2e59d6e00f6ccacc8064149ccc9fa5699f'::TEXT, ARRAY[1020]::BIGINT[]),
    (280::BIGINT, 'Excelente'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Respetado por los estudiantes', 'Aspectos de calificación claros']::TEXT[], '2017-01-18T00:00:00+00:00'::TIMESTAMPTZ, 'f6f38025cbeb41026423f7ee23021bccf39fdcaaae7f7f8dec128a23c4ab4410'::TEXT, ARRAY[1020]::BIGINT[]),
    (280::BIGINT, 'Excelente'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Respetado por los estudiantes']::TEXT[], '2017-01-15T00:00:00+00:00'::TIMESTAMPTZ, '0e7493824321eade381d239087fc363987a9664a443c2773d9d0886b37ad47a2'::TEXT, ARRAY[1030]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
